import {SpaceWork} from './space-model.mjs';
// A self-contained ground simulator. No real flight/suit operating instructions.
export async function mountSpace({stage,panel,flat=false,baseDelay=0,getDelay=()=>baseDelay,onBoltMistake=()=>0,onComplete,checkSession,work:providedWork=null,mode='full',onExit=null,onModeChange=()=>{}}){
 const work=providedWork||new SpaceWork();if(mode==='prepare')work.phase='suit';if(mode==='assembly')work.phase='inspect';if(mode==='cockpit')work.phase=work.results.length?'result':'design';let disposed=false,view=null,canvas=null,ctx=null,raf=0,last=performance.now(),cwristn=null,turnDrag=null,joystickId=null,input={x:0,y:0,throttle:0,brake:false},pulseUntil=0,needsDraw=true;
 const surface=document.createElement('div');surface.className='space-surface';stage.append(surface);document.body.classList.add('space-session');
 const delayNote=()=>mode==='cockpit'&&!work.repaired?`미조임 후속 확인 15분 · 현재 ${getDelay()}분 밀림 · 여기서 더 늘어나지 않아요`:work.repaired?`체결부 조정 완료 · 현재 ${getDelay()}분 밀림`:`조이지 않고 넘기면 +15분 · 현재 ${getDelay()}분 → 넘기면 ${getDelay()+15}분 밀림`;
 const statusNames={docked:'도킹 범위 안에서 정지했어요',fast:'접근 속도가 컸어요',offset:'중심에서 벗어났어요',fuel:'연료 여유를 다 썼어요',timeout:'시험 시간을 마쳤어요',stopped:'시험을 중지하고 기록했어요'};
 const $=id=>document.getElementById(id);const btn=(id,label)=>`<button class="wd-btn" id="${id}">${label}</button>`;
 async function setFlat(next){flat=next;onModeChange(flat);view?.dispose();view=null;surface.replaceChildren();canvas=document.createElement('canvas');canvas.id='spaceCanvas';canvas.setAttribute('aria-label','지상 시험 준비, 도킹 장치 모형과 조종석');surface.append(canvas);ctx=null;
  if(!flat){try{const {createSpaceView}=await import('./space-world.mjs');if(disposed)return;view=createSpaceView(canvas)}catch{flat=true;canvas.replaceWith(canvas=document.createElement('canvas'));canvas.id='spaceCanvas';surface.append(canvas)}}
  if(flat)ctx=canvas.getContext('2d');onModeChange(flat);render();
 }
 function point(id){if(view)return view.gearPoint(id);const b=canvas.getBoundingClientRect();return {x:b.width*({workwear:.43,badge:.55,wrist:.66}[id]),y:b.height*({workwear:.48,badge:.45,wrist:.57}[id])}}
 function boltPoint(id){if(view)return view.boltPoint(id);const b=canvas.getBoundingClientRect();const a=id*Math.PI/3,r=Math.min(b.width,b.height)*.3;return {x:b.width/2+Math.sin(a)*r,y:b.height/2-Math.cos(a)*r}}
 function flatDraw(){if(!ctx)return;const b=canvas.getBoundingClientRect(),w=b.width,h=b.height;canvas.width=w*devicePixelRatio;canvas.height=h*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);ctx.fillStyle=['flight','result'].includes(work.phase)?'#14223b':'#dce5e6';ctx.fillRect(0,0,w,h);
  if(work.phase==='suit'){ctx.fillStyle=work.gear.has('workwear')?'#7e9fba':'#fffdf8';ctx.fillRect(w*.4,h*.35,w*.2,h*.36);ctx.beginPath();ctx.arc(w*.5,h*.25,h*.12,0,Math.PI*2);ctx.fillStyle='#e3b98d';ctx.fill();for(const x of [.34,.66]){ctx.fillStyle='#e3b98d';ctx.fillRect(w*x-8,h*.53,16,22)}if(work.gear.has('badge')){ctx.fillStyle='#fffdf8';ctx.fillRect(w*.52,h*.4,18,25)}if(work.gear.has('wrist')){ctx.strokeStyle='#63a68d';ctx.lineWidth=6;ctx.strokeRect(w*.66-9,h*.56,18,6)}}
  else if(work.phase==='inspect'){ctx.strokeStyle='#90a9b6';ctx.lineWidth=12;ctx.beginPath();ctx.arc(w/2,h/2,Math.min(w,h)*.3,0,Math.PI*2);ctx.stroke();for(let i=0;i<6;i++){const p=boltPoint(i),done=work.turns[i]>=180;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(.3-work.turns[i]*Math.PI/180);ctx.strokeStyle=done?'#3f806b':'#df8552';ctx.lineWidth=done?2:8;ctx.strokeRect(-14,-14,28,28);ctx.fillStyle='#50657b';ctx.fillRect(-11,-11,22,22);ctx.restore()}}
  else if(work.phase==='design'){ctx.fillStyle='#5965ac';ctx.fillRect(w*.2,h*.45,w*.6,12);ctx.fillStyle='#f4f0e7';ctx.beginPath();ctx.moveTo(w*.5,h*.12);ctx.lineTo(w*.62,h*.67);ctx.lineTo(w*.38,h*.67);ctx.closePath();ctx.fill();ctx.fillStyle='#e0b754';ctx.fillRect(w*.43,h*.65,w*.14,10+work.config.power*4)}
  else{const t=work.trial,r=Math.min(h*.42,h*2/Math.max(2,t.distance));ctx.strokeStyle='#83cbb9';ctx.lineWidth=5;ctx.beginPath();ctx.arc(w/2-t.x*16,h/2+t.y*16,r,0,Math.PI*2);ctx.stroke();ctx.strokeStyle='#e7edf3';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(w/2-14,h/2);ctx.lineTo(w/2+14,h/2);ctx.moveTo(w/2,h/2-14);ctx.lineTo(w/2,h/2+14);ctx.stroke();ctx.fillStyle='#526277';ctx.fillRect(0,h-20,w,20)}
 }
 function overlays(){surface.querySelectorAll('.space-target').forEach(x=>x.remove());if(work.phase==='suit'&&cwristn){const p=point(cwristn),b=document.createElement('button');b.className='space-target gear-target';b.textContent='＋';b.setAttribute('aria-label','선택한 장비 착용 위치');b.style.left=p.x+'px';b.style.top=p.y+'px';b.onclick=()=>{if(checkSession()&&work.equip(cwristn)){cwristn=null;render()}};surface.append(b)}if(work.phase==='inspect')for(let id=0;id<6;id++){const p=boltPoint(id),b=document.createElement('button');b.className='space-target bolt-target';b.dataset.bolt=id;b.textContent=id+1;b.setAttribute('aria-label',`${id+1}번 체결부를 원을 그리며 점검하기`);b.style.left=p.x+'px';b.style.top=p.y+'px';b.onpointerdown=e=>{if(!checkSession())return;e.preventDefault();if(id!==work.nextBolt){const added=work.repaired?0:onBoltMistake(id,work.nextBolt);$('spaceDelay').textContent=delayNote();$('spaceHint').textContent=work.repaired?'여섯 체결부를 모두 조였어요.':'한쪽만 먼저 조이면 링이 비틀려요. '+(work.nextBolt+1)+'번을 먼저 조여요. '+(added?'순서 재확인 +2분.':'같은 순서 실수는 시간을 다시 더하지 않아요.');return}b.setPointerCapture(e.pointerId);const r=canvas.getBoundingClientRect();turnDrag={id:e.pointerId,bolt:id,angle:Math.atan2(e.clientY-r.top-p.y,e.clientX-r.left-p.x)};$('spaceHint').textContent=(id+1)+'번을 시계 방향으로 돌려요. 별 순서 1→4→2→5→3→6.'};b.onpointermove=e=>{if(turnDrag?.id!==e.pointerId)return;const r=canvas.getBoundingClientRect(),a=Math.atan2(e.clientY-r.top-p.y,e.clientX-r.left-p.x);let delta=a-turnDrag.angle;if(delta>Math.PI)delta-=Math.PI*2;if(delta<-Math.PI)delta+=Math.PI*2;work.tighten(delta*180/Math.PI,turnDrag.bolt);if(work.turns[turnDrag.bolt]>=180)$('spaceHint').textContent=work.repaired?'여섯 체결부를 모두 조였어요.':'다음은 '+(work.nextBolt+1)+'번이에요. 반대편으로 번갈아 조여요.';turnDrag.angle=a;$('boltProgress').textContent=`체결부 조정 ${Math.round(work.turn/180*100)}%${work.repaired?' · 틈이 닫혔어요':''}`;$('spaceDelay').textContent=delayNote();needsDraw=true};b.onpointerup=b.onpointercancel=b.onlostpointercapture=()=>turnDrag=null;surface.append(b)}}
 function clearInput(){input={x:0,y:0,throttle:0,brake:false};joystickId=null;turnDrag=null;if($('throttle'))$('throttle').value=0;if($('stickKnob'))$('stickKnob').style.transform='translate(-50%,-50%)'}
 function pause(){if(work.phase==='flight'){work.paused=true;clearInput();if($('resumeSpace'))$('resumeSpace').hidden=false}}
 const visibility=()=>{if(document.hidden)pause()};document.addEventListener('visibilitychange',visibility);window.addEventListener('blur',pause);
 function render(){if(disposed)return;document.body.dataset.spacePhase=work.phase;panel.scrollTop=0;const header=`<div class="space-heading"><span>${mode==='prepare'?'09:10 · 지상 시험 준비':mode==='assembly'?'10:30 · 조립대':'13:00 · 조종석 · 지상 시험'}</span><button id="spaceMode">${flat?'3D로 보기':'평면으로 보기'}</button></div>`;
  if(work.phase==='suit'){panel.innerHTML=header+`<h2>지상 시험 준비를 해요.</h2><details><summary>왜 준비할까요?</summary><p>작업복을 갖추고 출입증을 확인해요. 정전기 손목띠는 민감한 전자 부품을 다루는 준비예요. 실제 작업 절차를 단순화한 체험이에요.</p></details><div class="space-gear">${[['workwear','작업복'],['badge','출입증'],['wrist','손목띠']].map(([id,label])=>`<button data-gear="${id}" aria-pressed="${cwristn===id}">${work.gear.has(id)?'✓ ':''}${label} 집기</button>`).join('')}</div><p id="spaceHint">장비를 고른 뒤 인물의 ＋ 표시에 놓아요. ${work.gear.size}/3</p><div class="space-actions">${btn('suitReady',mode==='prepare'?'준비 마치고 시험동으로':'도킹 장치 설계대로 이동')}</div>`;panel.querySelectorAll('[data-gear]').forEach(b=>b.onclick=()=>{cwristn=b.dataset.gear;render()});$('suitReady').disabled=work.gear.size!==3;$('suitReady').onclick=()=>{if(checkSession()&&work.prepare()){if(mode==='prepare')onComplete({prepared:true});else render()}};}
  else if(work.phase==='design'){panel.innerHTML=header+`<h2>무인 화물선 도킹 장치를 설정해요.</h2><div class="ship-settings"><label>장비·기체 질량 <output id="massValue">${work.config.mass}</output><input id="shipMass" aria-label="화물선 모형 질량" type="range" min="1" max="3" value="${work.config.mass}"></label><label>추력 장치 <output id="powerValue">${work.config.power}</output><input id="shipPower" aria-label="추력 장치 크기" type="range" min="1" max="3" value="${work.config.power}"></label></div><label class="ship-assist"><input id="shipAssist" type="checkbox" ${work.config.assist?'checked':''}> 자세 안정 보조</label><details><summary>설계하면 무엇이 달라질까요?</summary><p>질량과 추력은 가속·연료에, 안정 보조는 잔류 움직임에 영향을 줘요.</p></details><div class="space-actions">${btn('inspectShip',mode==='cockpit'?'조종석에서 시험 시작':'실물 모형 체결부 살피기')}</div>`;for(const [id,key] of [['shipMass','mass'],['shipPower','power']])$(id).oninput=()=>{work.config[key]=Number($(id).value);$(key+'Value').textContent=work.config[key];needsDraw=true};$('shipAssist').onchange=()=>work.config.assist=$('shipAssist').checked;$('inspectShip').onclick=()=>{if(!checkSession())return;work.phase='inspect';if(mode==='cockpit')work.start();clearInput();render()};}
  else if(work.phase==='inspect'){panel.innerHTML=header+`<h2>별 순서로 링을 고르게 조여요.</h2><p id="spaceHint">1→4→2→5→3→6 순서예요. 볼트 둘레에 시계 방향 원을 그려요.</p><p id="spaceDelay" role="status">${delayNote()}</p><b id="boltProgress">체결부 조정 ${Math.round(work.turn/180*100)}%</b><details><summary>시험과 연결되는 점</summary><p>이 가상 모형은 느슨한 체결부가 있으면 우측으로 밀려요. 그대로 시험해 차이를 확인할 수도 있어요. 실제 정비 절차가 아니에요.</p></details><div class="space-actions">${btn('launchSpace',mode==='assembly'?'조립 기록 남기고 시험동으로':'조종석에서 도킹 시험')}${mode==='assembly'?'':btn('backDesign','설계 바꾸기')}</div>`;$('launchSpace').onclick=()=>{if(!checkSession())return;if(mode==='assembly'){onComplete({repaired:work.repaired});return}if(work.start()){clearInput();render()}};if($('backDesign'))$('backDesign').onclick=()=>{work.phase='design';render()};}
  else if(work.phase==='flight'){panel.innerHTML=header+`<div id="flightStats" role="status" aria-label="지상 시뮬레이터 시험 수치"></div><p id="spaceHint">조종간으로 중심을 맞추고, 추력을 줄여 천천히 접근해요.</p><div class="flight-controls"><div id="joystickSpace" role="group" aria-label="좌우 상하 조종간"><span id="stickKnob"></span></div><div><label>추력 <output id="throttleValue">0%</output><input id="throttle" aria-label="화물선 모형 추력 레버" type="range" min="0" max="100" value="0"></label><button id="brakeSpace">누르는 동안 감속</button></div></div><div class="nudge-controls" aria-label="조종간 대신 한 번씩 조작"><button data-nudge="left">←</button><button data-nudge="up">↑</button><button data-nudge="down">↓</button><button data-nudge="right">→</button></div><button id="resumeSpace" hidden>멈춘 시험 계속하기</button><div class="space-actions">${btn('stopSpace','중지·기록')}</div>`;
   const steering=document.createElement('div'),padNode=$('joystickSpace'),nudges=panel.querySelector('.nudge-controls');padNode.before(steering);steering.append(padNode,nudges);nudges.hidden=true;const toggle=document.createElement('button');toggle.id='steerMode';toggle.textContent='버튼 조종';toggle.onclick=()=>{const buttons=nudges.hidden;nudges.hidden=!buttons;padNode.hidden=buttons;toggle.textContent=buttons?'조종간':'버튼 조종';input.x=input.y=0};panel.querySelector('.space-actions').append(toggle);
   const pad=$('joystickSpace');const steer=e=>{const r=pad.getBoundingClientRect();input.x=Math.max(-1,Math.min(1,(e.clientX-r.left-r.width/2)/(r.width*.4)));input.y=-Math.max(-1,Math.min(1,(e.clientY-r.top-r.height/2)/(r.height*.4)));$('stickKnob').style.transform=`translate(calc(-50% + ${input.x*26}px),calc(-50% - ${input.y*26}px))`};pad.onpointerdown=e=>{if(!checkSession())return;e.preventDefault();joystickId=e.pointerId;pad.setPointerCapture(e.pointerId);steer(e)};pad.onpointermove=e=>{if(joystickId===e.pointerId)steer(e)};pad.onpointerup=pad.onpointercancel=pad.onlostpointercapture=()=>{input.x=input.y=0;joystickId=null;if($('stickKnob'))$('stickKnob').style.transform='translate(-50%,-50%)'};
   $('throttle').oninput=()=>{input.throttle=Number($('throttle').value)/100;$('throttleValue').textContent=$('throttle').value+'%'};const brake=$('brakeSpace');brake.onpointerdown=e=>{brake.setPointerCapture(e.pointerId);input.brake=true};brake.onpointerup=brake.onpointercancel=brake.onlostpointercapture=()=>input.brake=false;
   panel.querySelectorAll('[data-nudge]').forEach(b=>b.onclick=()=>{const v={left:[-1,0],right:[1,0],up:[0,1],down:[0,-1]}[b.dataset.nudge];[input.x,input.y]=v;pulseUntil=performance.now()+550});$('stopSpace').onclick=()=>{if(checkSession()&&work.trial.elapsed>=3){work.trial.stop();work.finish();clearInput();render()}};$('resumeSpace').hidden=!work.paused;$('resumeSpace').onclick=()=>{if(checkSession()){work.paused=false;panel.scrollTop=0;$('resumeSpace').hidden=true;last=performance.now()}};
  }else{const lastResult=work.results.at(-1);panel.innerHTML=header+`<h2>도킹 장치 시험 결과</h2><p id="spaceDelay" role="status">${delayNote()}</p><div class="space-results" aria-label="내 도킹 장치 비교 시험">${work.results.map((r,i)=>`<article class="space-result"><b>${i+1}차 · ${r.repaired?'조임':'틈 있음'}</b><span>연료 ${r.fuelUsed} · 중심 오차 ${r.offset} · 가로 밀림 ${r.drift}</span><details><summary>설계·접근 속도 보기</summary><p>질량 ${r.config.mass} / 추력 ${r.config.power} / 보조 ${r.config.assist?'켬':'끔'} · 접근 속도 ${r.speed}<br>${statusNames[r.status]} · ${r.seconds}초 시험</p></details></article>`).join('')}</div><div class="space-actions"><p id="spaceReason">${!work.comparable?'조건을 바꿔 두 번 비교해요.':!work.results.some(r=>r.fuelUsed>.2)?'추력을 사용한 시험 결과가 필요해요.':'비교 완료 · 다음 팀에 기록을 전달해요.'}<br>실패·중지의 추가 시간은 없어요.</p><div>${btn('retrySpace','재시험')}${btn('finishSpace',mode==='cockpit'?'시험 기록 들고 회의실로':'보고서')}</div></div>`;$('retrySpace').onclick=()=>{work.phase='design';render()};$('finishSpace').disabled=!work.comparable||!work.results.some(r=>r.fuelUsed>.2);$('finishSpace').onclick=()=>{if(checkSession()&&!$('finishSpace').disabled)onComplete({results:work.results.map(r=>({...r,config:{...r.config}})),repaired:work.repaired})};}
  if(['design','result','inspect'].includes(work.phase)){const actions=panel.querySelector('.space-actions'),content=document.createElement('div');content.className='space-content';for(const node of [...panel.childNodes])if(node!==actions)content.append(node);panel.replaceChildren(content,actions);}
  if(['flight','result'].includes(work.phase)){$('spaceMode').textContent=flat?'3D':'평면';panel.querySelector(work.phase==='result'?'.space-actions>div':'.space-actions').append($('spaceMode'));panel.querySelector('.space-heading').remove();}
  if(onExit&&work.phase!=='flight'){const back=document.createElement('button');back.id='returnHall';back.textContent='← 시험동으로';back.onclick=()=>{pause();onExit()};panel.querySelector('.space-actions').append(back)}
  $('spaceMode').onclick=async()=>{if(!checkSession())return;pause();$('spaceMode').disabled=true;await setFlat(!flat)};view?.draw(work);flatDraw();overlays();
 }
 function tick(now){if(disposed)return;if(!$('spaceMode')){clearInput();return;}const dt=Math.min(.05,(now-last)/1000);last=now;if(pulseUntil&&now>pulseUntil){input.x=input.y=0;pulseUntil=0}if(work.phase==='flight'&&!work.paused){work.trial.step(dt,input);if(work.trial.status!=='running'){work.finish();clearInput();render()}}
  if(needsDraw||work.phase==='flight'){view?.draw(work);flatDraw();needsDraw=false}if(work.phase==='flight'){const t=work.trial;$('flightStats').textContent=`지상 시험 · 거리 ${t.distance.toFixed(1)} · 속도 ${t.speed.toFixed(1)}\n연료 ${Math.round(t.fuel)} · 중심 오차 ${Math.hypot(t.x,t.y).toFixed(1)}`;$('stopSpace').disabled=t.elapsed<3;$('spaceHint').textContent=work.paused?'시험을 잠시 멈췄어요.':t.distance<4&&t.speed>.65?'가까워요. 감속 버튼을 누르고 추력을 낮춰요.':Math.hypot(t.x,t.y)>.55?`조종간을 ${t.x>.35?'왼쪽':t.x<-.35?'오른쪽':''}${Math.abs(t.x)>.35&&Math.abs(t.y)>.35?'·':''}${t.y>.35?'아래':t.y<-.35?'위':''}${Math.abs(t.y)>.35?'로':'으로'} 움직여 중심을 맞춰요.`:'중심이 맞아요. 낮은 속도로 접근해요.'}
  raf=requestAnimationFrame(tick);
 }
 const resize=()=>{if(disposed)return;view?.resize();view?.draw(work);flatDraw();if(!turnDrag)overlays()};const surfaceObserver=new ResizeObserver(resize);surfaceObserver.observe(surface);window.addEventListener('resize',resize);await setFlat(flat);raf=requestAnimationFrame(tick);
 return {dispose(){disposed=true;surfaceObserver.disconnect();cancelAnimationFrame(raf);clearInput();view?.dispose();surface.remove();document.body.classList.remove('space-session');delete document.body.dataset.spacePhase;document.removeEventListener('visibilitychange',visibility);window.removeEventListener('blur',pause);window.removeEventListener('resize',resize)}};
}
